import json
from src.nodes.base import BaseNode
from src.runtime.scene_validation import get_plausibility_engine

class Hou_Mcp_Scene_Plausibility(BaseNode):
    name = "hou_mcp_scene_plausibility"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("scene_layout_json", "string", widget_type="text", default="{}")
        self.add_output("plausibility_json")
        self.add_output("plausibility_score", "float")
        self.add_output("plausibility_valid", "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        raw = (inputs.get("scene_layout_json") or "").strip()
        try:
            scene = json.loads(raw) if raw else {}
        except Exception:
            self.log_error("scene_layout_json is not valid JSON.")
            return {"plausibility_json": "{}", "plausibility_score": 0.0, "plausibility_valid": False, "exec_out": True}
        try:
            result = get_plausibility_engine().evaluate(scene)
            for f in result.findings:
                self.log_error(f"Plausibility: {f}")
            return {
                "plausibility_json":  json.dumps(result.to_dict(), sort_keys=True, indent=2),
                "plausibility_score": result.plausibility_score,
                "plausibility_valid": result.plausibility_valid,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Plausibility evaluation failed: {exc}")
            return {"plausibility_json": "{}", "plausibility_score": 0.0, "plausibility_valid": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Scene_Plausibility
